by_url.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'url' && doc.url) {
    emit(doc.url, doc._id);
  }
}

by_path.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'url' && doc.path) {
    emit(doc.path, doc._id);
  }
}

by_domain.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'url' && doc.url) {
    try {
      var url = new URL(doc.url);
      emit(url.hostname, doc._id);
    } catch (e) {
      // Invalid URL, skip
    }
  }
}
